		for j < n && (isAlnum(s[j]) || s[j] == '_') {
			j++
		}
		return j
	}
	for j < n && ((s[j] >= '0' && s[j] <= '9') || s[j] == '_' || s[j] == '.') {
		j++
	}
	if j < n && (s[j] == 'e' || s[j] == 'E') {
		k := j + 1
		if k < n && (s[k] == '+' || s[k] == '-') {
			k++
		}
		if k < n && s[k] >= '0' && s[k] <= '9' {
			j = k
			for j < n && ((s[j] >= '0' && s[j] <= '9') || s[j] == '_') {
				j++
			}
		}
	}
