// confirmPreview is what the approver is shown: the call as the gate will compare it.
type confirmPreview struct {
	Method string `json:"method"`
	// URL is the path plus the canonical query — the form that is bound, so two spellings of one
	// query preview identically — with the values of secret-looking parameters withheld (they are
	// listed in Redacted, as "?name"). It is for reading, not comparing.
	URL string `json:"url"`
	// Path is the decoded path exactly as bound, never redacted: what a client compares.
	Path string `json:"path"`
	// BodyBytes is the size of the body as described; BodySHA256 is the hash of its canonical form,
	// which is the value in the binding.
	BodyBytes  int    `json:"body_bytes"`
	BodySHA256 string `json:"body_sha256"`
	// BodyKind says how Body renders: "none", "json", "text" or "binary" (a binary body is not shown,
	// only sized and hashed).
	BodyKind string `json:"body_kind"`
	// Body is the canonical body for display: pretty-printed JSON with secret-named members
	// redacted, or text. Truncated at maxPreviewBodyBytes, which BodyTruncated reports.
	Body          string `json:"body,omitempty"`
	BodyTruncated bool   `json:"body_truncated,omitempty"`
	// Redacted lists the JSON members whose values the preview withheld. The digest covers them; the
	// preview does not echo a password into a dialog, an MCP transcript or a log.
	Redacted []string `json:"redacted,omitempty"`
}

// secretMember matches the JSON member, query parameter and header names a preview withholds the
// value of. Over-matching costs a hidden value in a preview (the hash still binds it); under-matching
// echoes a secret into a dialog, an MCP transcript or a log.
var secretMember = regexp.MustCompile(`(?i)(pass(word|phrase)?|secret|token|api[_-]?key|private[_-]?key|credential|cookie|authorization|signature|(^|[_.-])(key|sig)$)`)

// redactedValue replaces a withheld value in a preview.
const redactedValue = "«redacted»"

// preview renders the binding for a human.
func (b callBinding) preview() confirmPreview {
	p := confirmPreview{
		Method:     b.method,
		URL:        b.path,
		BodyBytes:  b.rawLen,
		BodySHA256: hex.EncodeToString(b.bodySum[:]),
		BodyKind:   "none",
	}
	p.Path = b.path
	if b.query != "" {
		p.URL += "?" + redactQuery(b.query, &p.Redacted)
	}
	if len(b.body) == 0 {
		return p
	}
	var text string
	switch {
	case !utf8.Valid(b.body):
		p.BodyKind = "binary"
		return p
	case json.Valid(b.body):
		p.BodyKind = "json"
		dec := json.NewDecoder(bytes.NewReader(b.body))
		dec.UseNumber()
		var v any
		if err := dec.Decode(&v); err == nil {
			redacted := map[string]bool{}
			v = redactSecrets(v, redacted)
			if out, err := json.MarshalIndent(v, "", "  "); err == nil {
				text = string(out)
			}
			for k := range redacted {
				p.Redacted = append(p.Redacted, k)
			}
		}
		if text == "" {
			text = string(b.body)
		}
	default:
		p.BodyKind = "text"
		text = string(b.body)
	}
	if len(text) > maxPreviewBodyBytes {
		cut := maxPreviewBodyBytes
		for cut > 0 && !utf8.RuneStart(text[cut]) {
			cut--
		}
		text, p.BodyTruncated = text[:cut], true
	}
	p.Body = text
	sort.Strings(p.Redacted)
	return p
}

func (s *Server) handleUI2ScopeConfirm(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	model := map[string]any{
		"scope_action": r.PostFormValue("scope_action"),
		"kind":         r.PostFormValue("kind"),
		"pattern":      r.PostFormValue("pattern"),
		"path":         r.PostFormValue("path"),
		"port":         r.PostFormValue("port"),
		"protocol":     r.PostFormValue("protocol"),
		"enabled":      r.PostFormValue("enabled"),
		"old_kind":     r.PostFormValue("old_kind"),
		"old_pattern":  r.PostFormValue("old_pattern"),
		"old_path":     r.PostFormValue("old_path"),
		"old_port":     r.PostFormValue("old_port"),
		"old_protocol": r.PostFormValue("old_protocol"),
		"name":         r.PostFormValue("name"),
	}
	payload, errText := ui2ScopeAPIPayload(r)
	if errText == "" && strings.HasPrefix(r.PostFormValue("scope_action"), "library-") {
		// The review binds content, not a name: digests of the stored document and the live
		// list are computed from server state NOW and overwrite whatever the form carried,
		// and the sheet renders the exact lists those digests name.
		errText = s.ui2ScopeLibraryReview(r.PostFormValue("scope_action"), payload, model)
	}
	if errText != "" {
		model["error"] = errText
	} else {
		body, _ := ui2Marshal(payload)
		token, _, errText := s.ui2MintConfirm("/api/scope", http.MethodPost, "/api/scope", body)
		// The review copy says the confirmation covers "exactly the call above", so the
		// preview projects the FULL body, not ui2MintConfirm's 200-character abbreviation:
		// a library call carries two content digests that push it past that cut, and a
		// truncated body under an "exactly this call" claim is a label the bytes do not
		// keep (the session-rule review's full-projection rule applies here too).
		model["preview"] = fmt.Sprintf("%s %s — body %s", http.MethodPost, "/api/scope", string(body))
		model["token"] = token
		model["error"] = errText
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(ui2Exec("scope_confirm.html", model)))
}

// handleUI2ScopeRun serves POST /ui2/scope/run: spends the confirmation token on the exact
// /api/scope call the operator reviewed and re-renders the rules. A refusal (a missing or spent
// token, a body the token was not minted for, or the API's own reason such as a tuple that no
// longer matches a rule) renders as the note; the rules shown are the ones still in force.
func (s *Server) handleUI2ScopeRun(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	note := ""
	done := ""
	payload, errText := ui2ScopeAPIPayload(r)
	if errText != "" {
		note = errText
	} else {
		result, errText := s.ui2DispatchConfirmed(http.MethodPost, "/api/scope", payload, r.PostFormValue("token"))
		note = errText
		if errText == "" {
			done = ui2ScopeLibraryDoneNote(payload, result)
		}
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(ui2Exec("scope.html", s.ui2ScopeViewDone(note, done))))
}

